export function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0];const delimiter=first.includes('\t')?'\t':first.includes(';')?';':',';let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(field.trim());field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Hi ha cometes sense tancar al CSV.');row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows;}
export const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[ _-]+/g,' ');
export function csvRecords(text,kind){const rows=parseCSV(text);if(rows.length<2)throw Error('El fitxer ha de tenir una capçalera i almenys una fila.');const aliases=kind==='people'?{name:['nom','participant','nom complet'],phone:['telefon','telefon mobil'],origin:['origen','sortida'],arrival:['arribada','hora arribada'],ticket:['bitllet'],checkin:['check in','checkin'],pickup:['recollida'],parking:['parking','aparcament'],notes:['notes','observacions']}:{name:['vehicle','cotxe','nom'],driver:['conductor','conductora'],phone:['telefon','telefon conductor'],origin:['origen','sortida','punt de sortida'],departure:['hora','hora sortida','sortida hora'],direction:['trajecte','sentit'],seats:['places'],passengers:['passatgers'],parking:['parking','aparcament'],notes:['notes','observacions']};const headers=rows[0].map(normalize);const columns=Object.fromEntries(Object.entries(aliases).map(([k,vals])=>[k,headers.findIndex(h=>vals.includes(h))]));if(columns.name<0)throw Error(kind==='people'?'Falta la columna «Nom».':'Falta la columna «Vehicle» o «Cotxe».');return rows.slice(1).map((r,i)=>{const obj=Object.fromEntries(Object.entries(columns).map(([key,idx])=>[key,idx>=0?r[idx]||'':'']));if(!obj.name)throw Error(`Falta el nom a la fila ${i+2}.`);if(kind==='people'){obj.ticket=normalize(obj.ticket)==='comprat'?'Comprat':normalize(obj.ticket)==='no cal'?'No cal':'Pendent';obj.checkin=normalize(obj.checkin)==='fet'?'Fet':normalize(obj.checkin)==='no cal'?'No cal':'Pendent';}else{obj.direction=normalize(obj.direction)==='tornada'?'Tornada':'Anada';obj.seats=Number(obj.seats)||0;if(obj.seats<0||!Number.isInteger(obj.seats))throw Error(`Places incorrectes a la fila ${i+2}.`);}return obj;});}
export function pendingItems(t){const items=[];for(const p of t.people){if(p.ticket==='Pendent')items.push(`${p.name}: bitllet pendent`);if(p.checkin==='Pendent')items.push(`${p.name}: check-in pendent`);if(!p.pickup&&!p.vehicle)items.push(`${p.name}: transport sense assignar`);}for(const v of t.vehicles){if(!v.driver)items.push(`${v.name}: falta conductor`);if(!v.origin)items.push(`${v.name}: falta punt de sortida`);const assigned=t.people.filter(p=>p.vehicle===v.id).length;if(v.seats&&assigned>v.seats)items.push(`${v.name}: ${assigned} persones per a ${v.seats} places`);}return items;}
